void explicit_layout(const CodecVisitor::Buffer& b,const GrowthState& expected){GrowthState s;CodecVisitor c(b);auto no_entries=[](auto& x,auto&){return x.reject("UnexpectedFixtureEntry");};common_checkpoint::table(c,"actions",s.actions,no_entries);common_checkpoint::table(c,"facts",s.facts,no_entries);common_checkpoint::table(c,"life_activities",s.life_activities,[](CodecVisitor& v,LifeActivityRecord& r){v.object("view",[&](auto& x){return visit_life_activity_view(x,r.view);});v.object("context",[&](auto& x){return interaction_codec::visit_context(x,r.context);});Integer tag=-1;v.field("terms_kind",tag);check(tag==0,"slot3 Service terms tag0");r.terms=ServiceTerms{};v.object("terms",[&](auto& x){auto& t=std::get<ServiceTerms>(r.terms);x.field("duration",t.duration);x.field("cost",t.cost);x.field("wage",t.wage);x.field("hp_gain",t.hp_gain);x.field("fatigue_delta",t.fatigue_delta);x.field("wallet_id",t.wallet_id);return common_checkpoint::strings(x,"field_order",t.field_order);});v.field("cost_paid",r.cost_paid);v.field("wage_paid",r.wage_paid);common_checkpoint::strings(v,"field_order",r.field_order);common_checkpoint::strings(v,"view_field_order",r.view_field_order);auto empty=[](auto& x,auto&){return x.reject("UnexpectedSelectedTradeSource");};v.optional("selected_trade_settlement",r.selected_trade_settlement,empty);return v.optional("trade_terminal_time",r.trade_terminal_time,empty);});common_checkpoint::table(c,"fixed_service_boundaries",s.fixed_service_boundaries,visit_growth_fixed_service_boundary);check(c.finish().ok,"exact full ten slots plus final boundary table");same(expected,s);}
