int main(int argc,char** argv){try{const bool allocation_checks=!(argc==2&&std::string(argv[1])=="--without-allocation-failures");std::cerr<<"stage legacy\n";legacy_golden();std::cerr<<"stage roundtrip\n";roundtrip();original_prefix();std::cerr<<"stage strict shape\n";strict_selected_shape();std::cerr<<"stage JSON rejection\n";json_rejections();std::cerr<<"stage unsupported\n";unsupported();std::cerr<<"stage binary rejection\n";binary_tags();binary_rejections();std::cerr<<"stage allocation after "<<checks<<" checks\n";if(allocation_checks)allocation_failures();else std::cerr<<"allocation-failure gate explicitly not selected; normal functional checks only\n";std::cout<<"Growth G36 codec "<<checks<<" checks passed; real World owner/run closure not claimed\n";return 0;}catch(const std::exception& e){allocation_failure_after=-1;std::cerr<<"Growth G36 codec after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
